import { type FileSystem, type Telemetry, TelemetryFactory, parsePackageJson } from '@servicenow/sdk-build-core'
import { findRoot } from '../util/fshelpers'

export function createTelemetryClient(
    fileSystem: FileSystem,
    sdkDir: string = __dirname,
    instanceUrl?: URL
): Telemetry {
    const hostname = instanceUrl?.hostname

    const appSeeClient = TelemetryFactory.create({
        type: 'node',
        attributes: {
            sdkVersion: parsePackageJson(findRoot(sdkDir, fileSystem), fileSystem).version,
            clientName: 'cli',
            ...(hostname && { hostname }),
        },
    })

    return appSeeClient
}
